import {calculate} from './calc.mjs';
import {messages} from './i18n.js';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='en';try{if(localStorage.getItem('patungan-language')==='id')lang='id'}catch{}
let people=[],items=[],seq=0,currency='IDR',busy=false,pending=null,imageData=null,previewUrl=null,statusKey='',calculation,copyKey='';
const colors=['#e6ccb2','#d8ddc0','#edcfc2','#dbd1c4','#e6dbae','#cbd9d3'];
const currencies=['IDR','USD','EUR','GBP','CHF','SGD','MYR','AUD','JPY','THB','KRW','CNY','HKD','INR','PHP','VND','CAD','NZD','AED','SAR','TWD','BHD','KWD'];
const t=(key,args={})=>(messages[lang][key]||messages[lang].UPSTREAM).replace(/\{(\w+)\}/g,(_,k)=>args[k]??'');
const next=()=>String(++seq);
function digits(code=currency){return code==='IDR'?0:new Intl.NumberFormat('en',{style:'currency',currency:code}).resolvedOptions().maximumFractionDigits}
const scale=()=>10**digits(), step=code=>String(1/10**digits(code));
const minor=v=>{const n=Number(v);return Number.isFinite(n)&&n>=0&&n<=1e9?Math.round(n*scale()):NaN};
const amount=id=>minor($(id).value);
const money=n=>new Intl.NumberFormat(lang==='id'?'id-ID':'en',{style:'currency',currency,minimumFractionDigits:digits(),maximumFractionDigits:digits()}).format(n/scale());
function options(selected,blank=false){const list=[...new Set([...currencies,...(selected?[selected]:[])])];return (blank?`<option value="">${t('selectCurrency')}</option>`:'')+list.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('')}
function status(key){statusKey=key;$('#ocr-status').textContent=key?t(key):''}
function renderPeople(){$('#people-count').textContent=t('peopleCount',{n:people.length});$('#people').innerHTML=people.map((p,i)=>`<span class="person"><span class="avatar" style="--person-color:${colors[i%colors.length]}">${esc(p.name[0].toUpperCase())}</span>${esc(p.name)}<button data-remove-person="${p.id}" aria-label="${esc(t('remove',{name:p.name}))}">×</button></span>`).join('')}
function renderItems(){$('#item-count').textContent=t('itemCount',{n:items.length});$('#items').innerHTML=items.length?items.map(it=>`<article class="item" data-id="${it.id}"><div class="item-fields"><label>${t('itemName')}<input data-field="name" value="${esc(it.name)}" placeholder="${t('exampleItem')}" maxlength="100"></label><label>${t('price')} (${currency})<input data-field="price" type="number" min="0" max="1000000000" step="${step(currency)}" value="${esc(it.price)}"></label><button class="delete-item" data-delete="${it.id}" aria-label="${esc(t('remove',{name:it.name}))}">×</button></div><div class="assignments">${people.map(p=>`<button class="assign" data-owner="${p.id}" aria-pressed="${it.owners.includes(p.id)}">${esc(p.name)}</button>`).join('')}${people.length>1?`<button class="assign all" data-all="true">${t('everyone')}</button>`:''}</div><p class="assign-note">${!people.length?t('firstPeople'):!it.owners.length?t('notAssigned'):it.owners.length===1?t('alone'):t('shared',{n:it.owners.length})}</p></article>`).join(''):`<p class="empty-items">${t('emptyItems')}</p>`}
function update(){const tax=amount('#tax'),service=amount('#service'),discount=amount('#discount');const inputValid=items.every(i=>i.price!==''&&Number.isFinite(minor(i.price)))&&[tax,service,discount].every(Number.isSafeInteger);calculation=calculate(people,items.map(i=>({...i,price:minor(i.price)})),tax,service,discount);calculation.valid=calculation.valid&&inputValid;const c=calculation;
$('#grand-total').textContent=Number.isFinite(c.net)?money(c.net):'—';$('#subtotal').textContent=Number.isFinite(c.subtotal)?money(c.subtotal):'—';$('#extras').textContent=Number.isFinite(tax+service)?money(tax+service):'—';$('#discount-total').textContent=Number.isFinite(discount)?'− '+money(discount):'—';$('#unit').textContent=t('unit',{currency});
$('#results').innerHTML=people.length?people.map((p,i)=>`<div class="result"><div class="who"><span class="avatar" style="--person-color:${colors[i%colors.length]}">${esc(p.name[0].toUpperCase())}</span><span class="result-name">${esc(p.name)}<small>${t('itemCount',{n:items.filter(it=>it.owners.includes(p.id)).length})}</small></span></div><strong>${c.valid?money(c.shares[i]):'—'}</strong></div>`).join(''):`<p class="summary-empty">${t('emptySummary')}</p>`;
$('#unassigned').textContent=!inputValid||c.net<0||items.some(i=>!i.name.trim())?t('invalid'):c.unassigned?t('missing',{n:c.unassigned}):'';const check=$('#bill-total').value;$('#reconcile').textContent=check!==''&&Number.isFinite(c.net)?(minor(check)===c.net?t('match'):t('difference',{amount:money(Math.abs(minor(check)-c.net))})):'';$('#copy').disabled=!c.valid;$('#copy-status').textContent=copyKey?t(copyKey):''}
function render(){renderPeople();renderItems();update()}
function translate(){document.documentElement.lang=lang;document.title=t('title');document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));$('#person-name').placeholder=t('personPlaceholder');$('#person-name').setAttribute('aria-label',t('personPlaceholder'));$('#person-name').setCustomValidity('');$('#photo').setAttribute('aria-label',t('upload'));$('#receipt').alt=t('receiptAlt');$('#bill-total').placeholder=t('checkPlaceholder');$('#currency').innerHTML=options(currency);for(const id of ['tax','service','discount','bill-total'])$('#'+id).step=step(currency);status(statusKey);render();renderReview()}
function renderReview(){ $('#review').hidden=!pending;if(!pending)return;$('#review-currency').innerHTML=options(pending.currency,true);const warnings=[];if(!pending.currency)warnings.push(t('unknownCurrency'));if(pending.needsReview)warnings.push(t('uncertain'));if(pending.total!==null&&pending.items.every(i=>i.price!==null&&i.price!=='')){const sum=pending.items.reduce((s,i)=>s+Number(i.price),0)+Number(pending.tax)+Number(pending.service)-Number(pending.discount);if(Math.abs(sum-Number(pending.total))>0.011)warnings.push(t('mismatch'))}$('#review-warnings').textContent=warnings.join(' ');$('#review-warnings').hidden=!warnings.length;
$('#review-items').innerHTML=pending.items.map((it,i)=>`<div class="review-row" data-review-index="${i}"><label>${t('itemName')}<input data-review-field="name" maxlength="100" value="${esc(it.name)}"></label><label>${t('price')}<input data-review-field="price" type="number" min="0" max="1000000000" step="${step(pending.currency||'USD')}" value="${esc(it.price??'')}"></label><button class="delete-item" data-review-delete="${i}" aria-label="${esc(t('remove',{name:it.name}))}">×</button></div>`).join('');$('#review-charges').innerHTML=['tax','service','discount','total'].map(k=>`<label>${t(k==='total'?'billTotal':k)}<input data-review-charge="${k}" type="number" min="0" max="1000000000" step="${step(pending.currency||'USD')}" value="${esc(pending[k]??'')}"></label>`).join('');$('#review-error').textContent='';}
document.querySelectorAll('[data-lang]').forEach(el=>el.addEventListener('click',()=>{lang=el.dataset.lang;try{localStorage.setItem('patungan-language',lang)}catch{}translate()}));
$('#person-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#person-name'),name=input.value.trim();if(!name)return;if(people.some(p=>p.name.toLowerCase()===name.toLowerCase())){input.setCustomValidity(t('duplicate'));input.reportValidity();return}people.push({id:next(),name});input.value='';render();input.focus()});$('#person-name').addEventListener('input',()=>$('#person-name').setCustomValidity(''));
$('#people').addEventListener('click',e=>{const b=e.target.closest('[data-remove-person]');if(!b)return;people=people.filter(p=>p.id!==b.dataset.removePerson);items.forEach(i=>i.owners=i.owners.filter(id=>id!==b.dataset.removePerson));copyKey='';render()});
$('#add-item').addEventListener('click',()=>{items.push({id:next(),name:'',price:'',owners:[]});copyKey='';renderItems();update();$('#items .item:last-child input').focus()});
$('#items').addEventListener('input',e=>{if(!e.target.dataset.field)return;const it=items.find(i=>i.id===e.target.closest('.item').dataset.id);it[e.target.dataset.field]=e.target.value;copyKey='';update()});
$('#items').addEventListener('click',e=>{const a=e.target.closest('.item'),b=e.target.closest('button');if(!a||!b)return;const it=items.find(i=>i.id===a.dataset.id);if(b.dataset.delete)items=items.filter(i=>i.id!==it.id);else if(b.dataset.owner){const id=b.dataset.owner;it.owners=it.owners.includes(id)?it.owners.filter(v=>v!==id):[...it.owners,id]}else if(b.dataset.all)it.owners=people.map(p=>p.id);copyKey='';renderItems();update()});
for(const id of ['tax','service','discount','bill-total'])$('#'+id).addEventListener('input',()=>{copyKey='';update()});$('#currency').addEventListener('change',e=>{currency=e.target.value;copyKey='';translate()});
$('#demo').addEventListener('click',()=>{if(items.length&&!confirm(t('replaceDemo')))return;people=[{id:next(),name:t('you')},{id:next(),name:'Nadia'},{id:next(),name:'Dimas'}];items=[{id:next(),name:'Nasi goreng kampung',price:38000,owners:[people[0].id]},{id:next(),name:'Chicken katsu bowl',price:42000,owners:[people[1].id]},{id:next(),name:'Aglio olio',price:45000,owners:[people[2].id]},{id:next(),name:'Truffle fries',price:35000,owners:people.map(p=>p.id)}];currency='IDR';$('#tax').value=16000;$('#service').value=8000;$('#discount').value=0;$('#bill-total').value=184000;pending=null;imageData=null;$('#image-wrap').hidden=true;$('#retry-wrap').hidden=true;copyKey='';status('demoStatus');translate()});
function summary(){return ['PATUNGAN',...items.map(i=>`${i.name}: ${money(minor(i.price))} (${people.filter(p=>i.owners.includes(p.id)).map(p=>p.name).join(', ')})`),'',`${t('subtotal')}: ${money(calculation.subtotal)}`,`${t('tax')}: ${money(amount('#tax'))}`,`${t('service')}: ${money(amount('#service'))}`,`${t('discount')}: ${money(amount('#discount'))}`,`${t('total')}: ${money(calculation.net)}`,'',...people.map((p,i)=>`${p.name}: ${money(calculation.shares[i])}`)].join('\n')}
$('#copy').addEventListener('click',async()=>{if(!calculation.valid)return;try{await navigator.clipboard.writeText(summary());copyKey='copied'}catch{const el=document.createElement('textarea');el.value=summary();document.body.append(el);el.select();copyKey=document.execCommand('copy')?'copied':'copyFailed';el.remove()}update()});
$('#review').addEventListener('input',e=>{if(!pending)return;const field=e.target.dataset.reviewField,charge=e.target.dataset.reviewCharge;if(field){const i=Number(e.target.closest('[data-review-index]').dataset.reviewIndex);pending.items[i][field]=e.target.value}if(charge)pending[charge]=e.target.value===''?null:Number(e.target.value)});
$('#review-currency').addEventListener('change',e=>{pending.currency=e.target.value||null;renderReview()});
$('#review-items').addEventListener('click',e=>{const b=e.target.closest('[data-review-delete]');if(!b)return;pending.items.splice(Number(b.dataset.reviewDelete),1);renderReview()});
$('#apply').addEventListener('click',()=>{if(!pending)return;const validAmount=v=>v!==null&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=1e9;if(!pending.currency||!pending.items.length||pending.items.some(i=>!i.name.trim()||!validAmount(i.price))||['tax','service','discount'].some(k=>!validAmount(pending[k]))||(pending.total!==null&&!validAmount(pending.total))){$('#review-error').textContent=t('reviewError');return}if(items.length&&!confirm(t('replaceBill')))return;currency=pending.currency;items=pending.items.map(i=>({id:next(),name:i.name.trim(),price:Number(i.price),owners:[]}));for(const key of ['tax','service','discount'])$('#'+key).value=pending[key];$('#bill-total').value=pending.total??'';pending=null;copyKey='';status('applied');translate();$('#person-name').focus()});
$('#discard').addEventListener('click',()=>{pending=null;renderReview();status('discarded')});
function setBusy(value){busy=value;$('#photo').disabled=value;$('#demo').disabled=value;$('#retry').disabled=value;$('#apply').disabled=value;$('#discard').disabled=value;$('#progress').hidden=!value;$('#review').setAttribute('aria-busy',String(value))}
async function prepare(file){const bitmap=await createImageBitmap(file);try{const ratio=Math.min(1,2400/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL('image/jpeg',.9).split(',')[1];if(encoded.length>8e6)throw new Error('TOO_LARGE');return {mimeType:'image/jpeg',data:encoded}}finally{bitmap.close()}}
async function readAI(careful=false){if(!imageData)return;status('reading');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),65000);try{const response=await fetch('/api/receipt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...imageData,mode:careful?'careful':'standard'}),signal:controller.signal});let payload;try{payload=await response.json()}catch{throw new Error('UPSTREAM')}if(!response.ok)throw new Error(payload.error||'UPSTREAM');pending=payload.receipt;renderReview();status('ready')}catch(e){status(e.name==='AbortError'?'TIMEOUT':messages.en[e.message]?e.message:'NETWORK')}finally{clearTimeout(timer);$('#retry-wrap').hidden=false;setBusy(false)}}
async function readPhoto(file){if(!file||busy)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){status('fileType');return}if(file.size>15*1024*1024){status('fileSize');return}setBusy(true);pending=null;renderReview();$('#retry-wrap').hidden=true;status('preparing');try{imageData=null;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);$('#receipt').src=previewUrl;$('#image-wrap').hidden=false;imageData=await prepare(file);await readAI()}catch(e){status(e.message==='TOO_LARGE'?'TOO_LARGE':'invalidImage');setBusy(false)}finally{$('#photo').value=''}}
$('#retry').addEventListener('click',()=>{if(busy||!imageData)return;setBusy(true);readAI(true)});$('#photo').addEventListener('change',e=>readPhoto(e.target.files[0]));const drop=$('#drop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');readPhoto(e.dataTransfer.files[0])});
translate();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_bill_summary',description:'Read the current bill and assigned shares without changing anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({currency,total:calculation.net/scale(),ready:calculation.valid,shares:people.map((p,i)=>({name:p.name,amount:calculation.valid?calculation.shares[i]/scale():null}))})})).catch(()=>{})}catch{}}
